const raw = $input.first().json;
const item = (raw && typeof raw === 'object' && raw.body && typeof raw.body === 'object') ? raw.body : raw;
const errors = [];
const name = (item.name ?? '').toString().trim();
const email = (item.email ?? '').toString().trim();
const subject = (item.subject ?? '').toString().trim();
const message = (item.message ?? '').toString().trim();
const channel = ((item.channel ?? 'web').toString().trim().toLowerCase()) || 'web';

if (!name) errors.push('name is required');
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
if (!email) errors.push('email is required');
else if (!emailRe.test(email)) errors.push('email is not a valid email address');
if (!message) errors.push('message is required');

const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const stamp = now.getFullYear() + pad(now.getMonth() + 1) + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes()) + pad(now.getSeconds());
const rand = Math.floor(Math.random() * 0xffff).toString(16).padStart(4, '0');

const ticket = {
  id: 'TKT-' + stamp + '-' + rand,
  createdAt: now.toISOString(),
  channel, name, email, subject, message,
  text: (subject + ' ' + message).toLowerCase(),
};

return [{ json: { valid: errors.length === 0, errors, ticket } }];

// RULES-BASED triage — deterministic keyword scoring, no LLM.
// Production upgrade slot: replace this node with an AI Agent (OpenAI/Anthropic)
// that returns { category, priority } as structured output.
const { ticket } = $input.first().json;
const text = ' ' + ticket.text + ' ';
const hit = (kw) => text.includes(kw);

const CATEGORIES = {
  billing:   ['invoice', 'charged', 'charge', 'payment', 'refund', 'billing', 'subscription', 'receipt', 'overcharged'],
  technical: ['error', 'bug', 'crash', 'broken', 'timeout', 'api', ' 500 ', 'slow', 'down', 'outage', 'not working'],
  account:   ['login', 'password', 'sign in', 'locked', '2fa', 'two-factor', 'account', 'profile', 'invite', 'teammate', 'workspace', 'member'],
  order:     ['order', 'shipping', 'delivery', 'tracking', 'package', 'arrived', 'shipment'],
};
const URGENT = ['outage', 'down', 'hacked', 'fraud', 'breach', 'all users', "can't access", 'cannot access', 'data loss', 'security', 'urgent', 'asap', 'scam'];
const FRUSTRATED = ['angry', 'frustrated', 'terrible', 'awful', 'worst', 'scam', 'lawsuit'];
const PAYMENT_FAILURE = ['charged twice', 'unauthorized', 'failed payment', 'double charge', 'double charged'];

let category = 'general', best = 0;
const catHits = {};
for (const [cat, kws] of Object.entries(CATEGORIES)) {
  const hits = kws.filter(hit);
  catHits[cat] = hits;
  if (hits.length > best) { best = hits.length; category = cat; }
}
const urgentHits = URGENT.filter(hit);
const frustHits = FRUSTRATED.filter(hit);
const payFailHits = PAYMENT_FAILURE.filter(hit);

let priority = 'low';
if (urgentHits.length > 0 || (category === 'billing' && payFailHits.length > 0) || (frustHits.length >= 2 && category === 'technical')) {
  priority = 'high';
} else if (['technical', 'billing', 'order'].includes(category)) {
  priority = 'medium';
}

const slaHours = { high: 1, medium: 8, low: 24 }[priority];
const slaDeadline = new Date(Date.now() + slaHours * 3600 * 1000).toISOString();

return [{ json: {
  valid: true, errors: [], ticket,
  category, priority,
  matchedKeywords: { category: catHits[category] || [], urgent: urgentHits, frustration: frustHits, paymentFailure: payFailHits },
  slaHours, slaDeadline,
}}];

const input = $input.first().json;
const { ticket, category, priority, slaDeadline, kb } = input;
const article = kb.article;

const body = 'Hi ' + ticket.name + ',\n\n' +
  'Thanks for reaching out — this is an automated reply to your ticket ' + ticket.id + '.\n\n' +
  'This article from our help center should answer your question:\n\n' +
  article.title + '\n' + article.body + '\n' +
  'Read more: ' + article.link + '\n\n' +
  'Did this resolve your issue? If not, just reply to this message and a human agent will pick it up — your ticket stays open.\n\n' +
  'Best,\nSupport Team\n' +
  'Ticket: ' + ticket.id + ' · Category: ' + category + ' · Priority: ' + priority + ' · Respond-by: ' + slaDeadline;

return [{ json: {
  to: ticket.email,
  subject: 'Re: ' + (ticket.subject || 'Your support request') + ' [' + ticket.id + ']',
  body,
  record: {
    ticket,
    classification: { category, priority, matchedKeywords: input.matchedKeywords, slaHours: input.slaHours, slaDeadline },
    kb: { kbHit: kb.kbHit, score: kb.score, articleId: article.id, articleTitle: article.title },
  },
}}];

const compose = $('Compose auto-reply').first().json;
const sendResult = $input.first().json;
const r = compose.record;
const message = 'Ticket ' + r.ticket.id + ' was resolved automatically — the answer has been emailed to ' + r.ticket.email + '.';
return [{ json: {
  record: { ...r, outcome: 'auto_reply_sent', sentAt: new Date().toISOString(), outboundResponse: sendResult },
  ticketId: r.ticket.id,
  status: 'auto_resolved',
  category: r.classification.category,
  priority: r.classification.priority,
  slaDeadline: r.classification.slaDeadline,
  message,
}}];

const input = $input.first().json;
const { ticket, category, priority, slaDeadline, kb, matchedKeywords } = input;
const QUEUES = { billing: 'billing-queue', technical: 'eng-oncall', account: 'support-tier1', order: 'fulfillment', general: 'support-tier1' };
const summary = ticket.message.slice(0, 200);
const queue = QUEUES[category] || 'support-tier1';

const text = ':rotating_light: *New ' + priority.toUpperCase() + ' support ticket* ' + ticket.id + '\n' +
  '*Category:* ' + category + '\n' +
  '*Priority:* ' + priority + '\n' +
  '*SLA deadline:* ' + slaDeadline + '\n' +
  '*Customer:* ' + ticket.name + ' <' + ticket.email + '> (via ' + ticket.channel + ')\n' +
  '*Subject:* ' + (ticket.subject || '(no subject)') + '\n' +
  '*Summary:* ' + summary + '\n' +
  '*Suggested queue:* ' + queue + '\n' +
  '*KB article matched:* ' + (kb.kbHit ? kb.article.title : 'none');

return [{ json: {
  text,
  ticketId: ticket.id,
  queue,
  priority,
  category,
  slaDeadline,
  record: {
    ticket,
    classification: { category, priority, matchedKeywords, slaHours: input.slaHours, slaDeadline },
    kb: { kbHit: kb.kbHit, score: kb.score, articleId: kb.article ? kb.article.id : null, articleTitle: kb.article ? kb.article.title : null },
  },
}}];

const compose = $('Compose escalation').first().json;
const sendResult = $input.first().json;
const r = compose.record;
const message = 'Ticket ' + r.ticket.id + ' has been escalated to a human agent (' + compose.queue + ', ' + r.classification.priority + ' priority). Expected response by ' + r.classification.slaDeadline + '.';
return [{ json: {
  record: { ...r, outcome: 'escalation_sent', sentAt: new Date().toISOString(), outboundResponse: sendResult },
  ticketId: r.ticket.id,
  status: 'escalated_to_human',
  category: r.classification.category,
  priority: r.classification.priority,
  slaDeadline: r.classification.slaDeadline,
  message,
}}];

// Write the ticket record as JSON using Node's fs.
// Requires NODE_FUNCTION_ALLOW_BUILTIN=fs on the n8n instance.
const fs = require('fs');
const input = $input.first().json;
const dir = $env.HELPDESK_DATA_DIR || '/tmp/helpdesk-data';
const fileName = dir + '/ticket-' + input.ticketId + '.json';
fs.writeFileSync(fileName, JSON.stringify(input.record, null, 2));
return [{ json: { ...input, fileWritten: fileName } }];
